#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define IS_ALIGNED(p, a)  (((uintptr_t)(p) & ((a) - 1)) == 0)
#define ALIGN_UP(x, a)    (((x) + (a) - 1) & ~(uintptr_t)((a) - 1))

int main(void) {
    char *buf = malloc(64);
    printf("buf     %p aligned to 16? %d\n", (void *)buf, IS_ALIGNED(buf, 16));
    printf("buf + 1 %p aligned to 4?  %d\n", (void *)(buf + 1), IS_ALIGNED(buf + 1, _Alignof(int)));
    uintptr_t up = ALIGN_UP((uintptr_t)(buf + 1), _Alignof(double));
    printf("next 8-aligned address: %p (+%d bytes)\n", (void *)up, (int)(up - (uintptr_t)buf));
    free(buf);
}

/* Output (clang -O2, arm64 Mac):
buf     0x10128dd20 aligned to 16? 1
buf + 1 0x10128dd21 aligned to 4?  0
next 8-aligned address: 0x10128dd28 (+8 bytes) */

#include <stdlib.h>

struct vec {
    size_t n;
    double data[];   /* flexible array member: no size */
};

struct vec *vec_new(size_t n) {
    struct vec *v = malloc(sizeof(struct vec) + n * sizeof(double));
    if (v) v->n = n;
    return v;          /* v->data[0] .. v->data[n - 1] are usable */
}

/* sizeof(struct vec) == 8 and offsetof(struct vec, data) == 8
   on arm64 and x86-64 (measured). */

#include <stdint.h>
#include <string.h>

uint32_t read_len(const unsigned char *buf) {
    /* BUG: buf + 1 is not 4-aligned */
    const uint32_t *p = (const uint32_t *)(buf + 1);
    return *p;
}

uint32_t read_len_ok(const unsigned char *buf) {
    uint32_t v;
    memcpy(&v, buf + 1, sizeof v);  /* any alignment */
    return v;
}

