#include <stdint.h>
#include <string.h>

uint32_t float_bits(float f) {
    uint32_t u;
    memcpy(&u, &f, sizeof u);    /* legal in C and C++ */
    return u;
}

uint32_t float_bits_union(float f) {
    union { float f; uint32_t u; } pun = { .f = f };
    return pun.u;                /* legal in C, not in ISO C++ */
}

/* float_bits(1.0f) == 0x3f800000.
   clang -O2, arm64: both functions are   fmov w0, s0 ; ret */

#include <arpa/inet.h>   /* ntohl */
#include <stdint.h>
#include <stdio.h>
#include <string.h>

struct __attribute__((packed)) hdr { uint8_t type; uint32_t len; };

int main(void) {
    uint32_t x = 0x0A0B0C0D;
    unsigned char m[4];
    memcpy(m, &x, 4);
    printf("in memory: %02X %02X %02X %02X\n", m[0], m[1], m[2], m[3]);

    unsigned char wire[5] = {0x01, 0x00, 0x00, 0x01, 0x2C}; /* type 1, len 300 */
    struct hdr h;
    memcpy(&h, wire, sizeof h);
    printf("h.len raw  = %u (0x%08X)\n", h.len, h.len);
    printf("ntohl(len) = %u\n", ntohl(h.len));
}

/* Output (clang -O2, arm64 Mac):
in memory: 0D 0C 0B 0A
h.len raw  = 738263040 (0x2C010000)
ntohl(len) = 300 */

uint32_t get_be32(const unsigned char *b) {
    uint32_t v = 0;
    v |= (uint32_t)b[0] << 24;
    v |= (uint32_t)b[1] << 16;
    v |= (uint32_t)b[2] << 8;
    v |= (uint32_t)b[3];
    return v;
}

/* wire bytes 1 to 4 of the message:  00 01 11 70 */

#include <stdint.h>
#include <stdio.h>

/* Wire format, 7 bytes: type u8, len u32 big-endian, flags u16 big-endian */
struct msg { uint8_t type; uint32_t len; uint16_t flags; };  /* 12 bytes in memory */

void put_msg(unsigned char out[7], const struct msg *m) {
    out[0] = m->type;
    out[1] = m->len >> 24; out[2] = m->len >> 16;
    out[3] = m->len >> 8;  out[4] = m->len;
    out[5] = m->flags >> 8; out[6] = m->flags;
}

struct msg get_msg(const unsigned char in[7]) {
    struct msg m;
    m.type  = in[0];
    m.len   = (uint32_t)in[1] << 24 | (uint32_t)in[2] << 16 |
              (uint32_t)in[3] << 8  | in[4];
    m.flags = (uint16_t)(in[5] << 8 | in[6]);
    return m;
}

int main(void) {
    struct msg m = { 2, 70000, 0x8001 };
    unsigned char wire[7];
    put_msg(wire, &m);
    for (int i = 0; i < 7; i++) printf("%02X ", wire[i]);
    struct msg r = get_msg(wire);
    printf("\ntype=%u len=%u flags=0x%04X\n", r.type, r.len, r.flags);
}

/* Output:
02 00 01 11 70 80 01
type=2 len=70000 flags=0x8001 */

