struct user      { uint64_t id; uint32_t flags; uint32_t score;
                   char name[48]; char email[64]; };         /* 128 bytes */

struct user_hot  { uint64_t id; uint32_t flags; uint32_t cold; }; /* 16 bytes */
struct user_cold { uint32_t score; char name[48]; char email[64]; };

/* Scan 1,000,000 records for a flag bit (best of 20, arm64 Mac):
   struct user[]      128 MB touched   4.06 ms
   struct user_hot[]   16 MB touched   0.22 ms */

#include <stdalign.h>
#include <stdatomic.h>

#define ITERS 100000000L
struct same  { atomic_long a; atomic_long b; };                          /* one line */
struct split { alignas(64) atomic_long a; alignas(64) atomic_long b; };  /* two lines */

static void *inc(void *p) {          /* run by two threads, one per counter */
    atomic_long *c = p;
    for (long i = 0; i < ITERS; i++)
        atomic_fetch_add_explicit(c, 1, memory_order_relaxed);
    return 0;
}

/* Wall time for both threads, 3 runs, clang -O2 on an arm64 Mac:
   same line       0.93 s   1.25 s   0.90 s
   separate lines  0.21 s   0.25 s   0.26 s */

#include <assert.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

struct arena { unsigned char *base; size_t cap, used; };

static void *arena_alloc(struct arena *a, size_t size, size_t align) {
    uintptr_t start = (uintptr_t)a->base + a->used;
    uintptr_t p = (start + align - 1) & ~(uintptr_t)(align - 1); /* align_up */
    size_t need = (p - (uintptr_t)a->base) + size;
    if (need > a->cap) return NULL;           /* out of space */
    a->used = need;
    return (void *)p;
}
#define NEW(a, T) ((T *)arena_alloc((a), sizeof(T), _Alignof(T)))

int main(void) {
    static _Alignas(16) unsigned char mem[256];
    struct arena a = { mem, sizeof mem, 0 };
    char   *c = NEW(&a, char);
    double *d = NEW(&a, double);
    short  *s = NEW(&a, short);
    assert((uintptr_t)d % _Alignof(double) == 0);
    assert((uintptr_t)s % _Alignof(short) == 0);
    printf("c@%td d@%td s@%td used=%zu\n", (unsigned char *)c - mem,
           (unsigned char *)d - mem, (unsigned char *)s - mem, a.used);
}

/* Output: c@0 d@8 s@16 used=18 */
